let boxSize = 35;
let allCubes = [];

class Cube {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.rot = createVector(0, 0);
    this.spinX = random(-0.02, 0.02);
    this.spinY = random(-0.02, 0.02);
    this.hueValue = random(255);
  }

  update(bass = 0, perc = 0) {
    this.spinX += (noise(this.pos.x * 0.01, frameCount * 0.02) - 0.5) * 0.05 + bass * 0.05;
    this.spinY += (noise(this.pos.y * 0.01, frameCount * 0.02) - 0.5) * 0.05 + perc * 0.05;
    this.rot.x += this.spinX;
    this.rot.y += this.spinY;
    this.spinX *= 0.95;
    this.spinY *= 0.95;
    this.hueValue = (this.hueValue + 0.5 + bass * 2) % 255;
  }

  display(bass = 0) {
    push();
    translate(this.pos.x, this.pos.y, 0);
    rotateY(this.rot.x);
    rotateX(this.rot.y);
    fill(this.hueValue, 200, 240);
    stroke(0, 40);
    strokeWeight(1);
    box(boxSize * (1.0 + bass * 0.4));
    pop();
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(HSB, 255);
  initCubes();
}

function initCubes() {
  allCubes = [];
  let step = boxSize * 1.6;
  let halfW = width / 2;
  let halfH = height / 2;
  for (let y = -halfH + step; y < halfH - step; y += step) {
    for (let x = -halfW + step; x < halfW - step; x += step) {
      allCubes.push(new Cube(x, y));
    }
  }
}

function draw() {
  let bass = (typeof sub_bass !== undefined) ? sub_bass : (typeof bass_ratio !== undefined ? bass_ratio : 0);
  let perc = (typeof percussive !== undefined) ? percussive : 0;
  background(20, 20, 30);
  if (allCubes.length === 0 || frameCount === 1) {
    initCubes();
  }
  for (let c of allCubes) {
    c.update(bass, perc);
    c.display(bass);
  }
}
